-- ============================================================================
-- 0009 — storage: private bucket + workspace-scoped path policy
-- ============================================================================
-- Layout: nexus-documents/{workspace_id}/{document_id}/{filename}
--
-- The tenant segment is the WORKSPACE, not the user: a member who joins a
-- workspace must be able to download its files, so a per-user path without a
-- membership lookup would either break sharing or leak across tenants.
--
-- The bucket is private. Bytes move via signed URLs (generated by the API with
-- the service role) or direct authenticated uploads from a member.
-- ============================================================================

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'nexus-documents',
  'nexus-documents',
  false,
  52428800, -- 50 MiB
  array[
    'application/pdf',
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    'application/msword',
    'text/plain',
    'text/markdown'
  ]
)
on conflict (id) do update
  set public             = excluded.public,
      file_size_limit    = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

-- ---------------------------------------------------------------------------
-- Policies on storage.objects: the first path segment must be a workspace the
-- caller belongs to. Reads need membership; writes need write permission, so a
-- viewer can download but not upload.
-- ---------------------------------------------------------------------------
drop policy if exists nexus_objects_select_member on storage.objects;
create policy nexus_objects_select_member on storage.objects
  for select to authenticated
  using (
    bucket_id = 'nexus-documents'
    and public.is_workspace_member(
      nullif((storage.foldername(name))[1], '')::uuid
    )
  );

drop policy if exists nexus_objects_insert_write on storage.objects;
create policy nexus_objects_insert_write on storage.objects
  for insert to authenticated
  with check (
    bucket_id = 'nexus-documents'
    and public.can_write_workspace(
      nullif((storage.foldername(name))[1], '')::uuid
    )
  );

drop policy if exists nexus_objects_update_write on storage.objects;
create policy nexus_objects_update_write on storage.objects
  for update to authenticated
  using (
    bucket_id = 'nexus-documents'
    and public.can_write_workspace(
      nullif((storage.foldername(name))[1], '')::uuid
    )
  )
  with check (
    bucket_id = 'nexus-documents'
    and public.can_write_workspace(
      nullif((storage.foldername(name))[1], '')::uuid
    )
  );

drop policy if exists nexus_objects_delete_write on storage.objects;
create policy nexus_objects_delete_write on storage.objects
  for delete to authenticated
  using (
    bucket_id = 'nexus-documents'
    and public.can_write_workspace(
      nullif((storage.foldername(name))[1], '')::uuid
    )
  );
